  {bound : κ → β → Prop} {entries : Std.ExtTreeMap κ β compare}
  {valid : ∀ (k : κ) (v : β), entries[k]? = some v → k ∈ required ∧ bound k v} {entries_1 : Std.ExtTreeMap κ β compare}
  {valid_1 : ∀ (k : κ) (v : β), entries_1[k]? = some v → k ∈ required ∧ bound k v},
  { entries := entries, valid := valid } = { entries := entries_1, valid := valid_1 } → entries = entries_1

∀ {κ : Type u} {β : Type v} [inst : Ord κ] [inst_1 : Std.TransOrd κ] {required : StrictLeanPolicy.CanonicalSet κ}
  {bound : κ → β → Prop} (self : StrictLeanPolicy.ResultState required bound) (k : κ) (v : β),
  self.entries[k]? = some v → k ∈ required ∧ bound k v
